#requires -version 5.1
param()
$ErrorActionPreference='Stop'
$projectRoot=Split-Path $PSScriptRoot -Parent
Set-Location -LiteralPath $projectRoot
Import-Module (Join-Path $projectRoot 'app\CleanData\MemoryClear.Disk.psm1') -Force
$artifactRoot=Join-Path $projectRoot 'artifacts';$fixtureRoot=Join-Path $artifactRoot ('disk-fixture-'+[guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $fixtureRoot|Out-Null;[IO.File]::WriteAllText((Join-Path $fixtureRoot '.memoryclear-fixture'),'Guard tests own this disposable directory')
$results=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Condition,[string]$Message='Assertion failed');if(-not$Condition){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Test);try{&$Test;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}}
function NewFixture {param([string]$Name);$path=Join-Path $fixtureRoot $Name;[IO.File]::WriteAllText($path,'Disposable content');return $path}
function MoveFixture {param([string]$Source,[string]$Destination);if(-not[MemoryClear.Storage.FileInventory]::Within([IO.Path]::GetFullPath($Source),$fixtureRoot)-or-not[MemoryClear.Storage.FileInventory]::Within([IO.Path]::GetFullPath($Destination),$fixtureRoot)){throw 'Move targets must stay inside this test fixture.'};Move-Item -LiteralPath $Source -Destination $Destination}
Check 'Guard deletes only unchanged disposable fixture through stable handle' {$p=NewFixture 'delete-me.txt';$id=[MemoryClear.Storage.FileInventory]::Snapshot($p,$fixtureRoot);[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot);Assert (-not(Test-Path -LiteralPath $p))}
Check 'Changed content/timestamp rejected and preserved' {$p=NewFixture 'changed.txt';$id=[MemoryClear.Storage.FileInventory]::Snapshot($p,$fixtureRoot);[IO.File]::AppendAllText($p,'new content');$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $p))}
Check 'Replaced file identity rejected' {$p=NewFixture 'replaced.txt';$id=[MemoryClear.Storage.FileInventory]::Snapshot($p,$fixtureRoot);MoveFixture $p ($p+'.old');[IO.File]::WriteAllText($p,'New independent file');$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $p))}
Check 'Locked fixture rejected without killing owner' {$p=NewFixture 'locked.txt';$id=[MemoryClear.Storage.FileInventory]::Snapshot($p,$fixtureRoot);$lock=[IO.File]::Open($p,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None);try{$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $p))}finally{$lock.Dispose()}}
Check 'Path/parent junction swap rejected; target preserved' {$folder=Join-Path $fixtureRoot 'original';$target=Join-Path $fixtureRoot 'target';New-Item -ItemType Directory -Path $folder,$target|Out-Null;[IO.File]::WriteAllText((Join-Path $folder 'file.txt'),'Original fixture');[IO.File]::WriteAllText((Join-Path $target 'file.txt'),'Keep target');$id=[MemoryClear.Storage.FileInventory]::Snapshot((Join-Path $folder 'file.txt'),$fixtureRoot);MoveFixture $folder ($folder+'-moved');New-Item -ItemType Junction -Path $folder -Target $target|Out-Null;$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath (Join-Path $target 'file.txt')))}
Check 'Hardlink created after preview rejects deletion' {$p=NewFixture 'linked.txt';$id=[MemoryClear.Storage.FileInventory]::Snapshot($p,$fixtureRoot);New-Item -ItemType HardLink -Path ($p+'.alias') -Target $p|Out-Null;$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $p))}
Check 'Parent replacement rejected even with the original file identity' {$parent=Join-Path $fixtureRoot 'parent-replace';New-Item -ItemType Directory -Path $parent|Out-Null;$p=Join-Path $parent 'same-file.txt';[IO.File]::WriteAllText($p,'Original');$id=[MemoryClear.Storage.FileInventory]::Snapshot($p,$fixtureRoot);MoveFixture $parent ($parent+'.old');New-Item -ItemType Directory -Path $parent|Out-Null;MoveFixture (Join-Path ($parent+'.old') 'same-file.txt') $p;$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $p))}
Check 'Outside root and protected fixture marker cannot delete' {$marker=Join-Path $fixtureRoot '.memoryclear-fixture';$id=[MemoryClear.Storage.FileInventory]::Snapshot($marker,$fixtureRoot);$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $marker));$id.Path=Join-Path $projectRoot 'README.md';$blocked=$false;try{[MemoryClear.Storage.FileInventory]::DeleteFixture($id,$artifactRoot)}catch{$blocked=$true};Assert ($blocked-and(Test-Path -LiteralPath $id.Path))}
Check 'General scanner deletion disabled; Temp entry uses separate reviewed capability' {Assert (-not(Get-MCDiskPolicy).executionEnabled);Assert ((Get-Content (Join-Path $projectRoot 'app\CleanData\DiskView.ps1') -Raw)-match'DiskClean.Add_Click\(\{Show-MCTempCleanup\}\)');$fixtureSnapshot=[MemoryClear.Storage.FileInventory]::Snapshot((Join-Path $fixtureRoot '.memoryclear-fixture'),$fixtureRoot);$blocked=$false;try{[MemoryClear.Storage.FileInventory]::ValidateOwnTemp($fixtureSnapshot,7)}catch{$blocked=$true};Assert $blocked}
$report=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Results=$results.ToArray();Scope='Native destructive guard invoked exclusively on test-owned marked disk-fixture directories under workspace artifacts';RealUserCleanupExecuted=$false;Unverified=@('Production deletion authority/manifest/backup/journal','Win10/Win11 VM matrix','Concurrent parent swap during held-handle operation')}
$report|ConvertTo-Json -Depth 6|Set-Content (Join-Path $projectRoot 'docs\verification\disk-guard-tests.json') -Encoding UTF8
$results|Format-Table -AutoSize|Out-String|Write-Output
if($report.Failed-gt0){exit 1}
